const company = $('When Executed by Another Workflow').first().json.company_name;
const companySearch = $('HTTP Request').first().json;
const requests = $('Code in JavaScript1').all().map(i=>i.json);
const responses = $input.all().map(i=>i.json);
const clean = x => (Array.isArray(x.results)?x.results:[]).filter(r=>typeof r.url==='string'&&/^https?:\/\//i.test(r.url)).map(r=>({title:r.title||'',url:r.url,content:r.content||''}));
const companySources=clean(companySearch).slice(0,15);
const key=String(company).toLowerCase().replace(/[^a-z0-9]/g,'');
const role=/sales|revenue|account executive|solutions engineer|solution consultant|sales engineer|presales|talent acquisition|recruiter|recruiting/i;
const rank=r=>{
 const text=r.title+' '+r.content;
 const profile=/^https?:\/\/(?:[^/]+\.)?linkedin\.com\/in\//i.test(r.url);
 const site=r.url.split('/')[2]?.replace(/[^a-z0-9]/gi,'').toLowerCase().includes(key);
 return (profile?8:0)+(site?5:0)+(role.test(r.title)?6:role.test(text)?2:0)+(text.toLowerCase().includes(String(company).toLowerCase())?4:0)-(/linkedin\.com\/(?:jobs|company)|\/careers|job openings/i.test(r.url)?10:0);
};
const queues=responses.map((r,i)=>clean(r).map(s=>({...s,category:requests[i]?.category||'unknown',query:r.query||requests[i]?.query||''})).sort((a,b)=>rank(b)-rank(a)));
const seen=new Set(), contactSources=[];
for(let p=0;p<15;p++) for(const queue of queues){
 const r=queue[p]; if(!r)continue;
 const dedup=r.url.split('?')[0].replace(/\/$/,'');
 if(!seen.has(dedup)){seen.add(dedup);contactSources.push(r);}
}
const diagnostics=responses.map((r,i)=>({category:requests[i]?.category||'unknown',query:r.query||requests[i]?.query||'',result_count:clean(r).length,errors:r.unresponsive_engines||[]}));
return [{json:{output:{company,status:contactSources.length?'CONTACT_LEADS_REQUIRE_VERIFICATION':'NO_CONTACT_EVIDENCE',company_sources:companySources,contact_sources:contactSources,company_search_errors:companySearch.unresponsive_engines||[],contact_search_errors:diagnostics.filter(d=>d.errors.length),contact_search_diagnostics:diagnostics,research_summary_unverified:''}}}];

const input=$('When Executed by Another Workflow').first().json;
const company=String(input.company_name||'').trim();
if(!company)throw new Error('company_name is required');
const result=$input.first().json;
if(!(result.results||[]).length&&(result.unresponsive_engines||[]).length)throw new Error('Search providers unavailable; use sourced contact directory until providers recover.');
const name='"'+company.replace(/["\r\n]/g,'')+'"';
const manager=String(input.research_request||'').match(/(?:Department Leader|Hiring Manager|Reports to)\s*:\s*([A-Z][a-z]+(?:[ -][A-Z][a-z]+){1,4})\s*\|/i)?.[1];
const queries={talent_acquisition:name+' ("hiring team" OR "contact person" OR recruiter OR "talent acquisition") careers jobs',revenue:name+' ("chief revenue officer" OR CRO OR "VP of Sales" OR "Head of Sales") leadership',sales:name+' ("Director of Sales" OR "VP Sales" OR "Head of Sales" OR "Account Management") team',solutions_engineering:name+' '+(manager?'"'+manager+'" sales engineering':'("Director of Solutions Engineering" OR "Director of Sales Engineering" OR "Head of Solutions Engineering" OR "Sales Engineering Manager")')};
const focus=String(input.contact_focus||'general').trim().toLowerCase().replace(/ /g,'_');
const categories=focus==='general'?Object.keys(queries):[Object.hasOwn(queries,focus)?focus:'talent_acquisition'];
return categories.map(category=>({json:{category,query:queries[category]}}));
